 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"

/* Include the Exo-generated kernel header. */
#include "generated/durbin/durbin.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:

   Optimizations vs. the baseline PolyBench/Exo kernel:

   - Algorithmic:
     * Eliminate the temporary vector z[n] by doing a symmetric in-place
       update of y[0..k-1] using pairwise updates (i, k-1-i). This is
       mathematically and bitwise equivalent to the original two-loop
       formulation:
           z[i] = y[i] + alpha * y[k-1-i]
           y[i] = z[i]
       but halves the memory traffic on y and removes the O(n) scratch.

     * Split the in-place update into:
         - a branch-free loop over disjoint pairs (i, k-1-i)
         - an optional single-center update when k is odd
       This improves vectorization and reduces branch mispredictions.

   - Scheduling:
     * Use Exo scheduling primitives to unroll the reduction loop over i
       (for the dot-product sum) and the in-place update loop over i by
       a small constant factor, improving ILP and SIMD efficiency while
       preserving the original floating-point evaluation order.
*/
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


@proc
def kernel_durbin(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    assert n > 0

    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE

    # Initial conditions (k = 0)
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    # Main Durbin / Levinson–Durbin recursion for k = 1..n-1.
    # This loop is inherently sequential in k and is left as-is.
    for k in seq(1, n):
        # Update beta using the previous reflection coefficient alpha.
        beta = (1.0 - alpha * alpha) * beta

        # Dot-product-like reduction:
        #   sum = Σ_{i=0}^{k-1} r[k-1-i] * y[i]
        # This is kept strictly sequential in i to preserve FP order;
        # unrolling below does not change the order of operations.
        sum = 0.0
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        # New reflection coefficient for order k.
        alpha = -(r[k] + sum) / beta

        # In-place symmetric update of y[0..k-1], eliminating z[n]:
        #
        # Original kernel:
        #   for i in 0..k-1:
        #       z[i] = y[i] + alpha * y[k-1-i]
        #   for i in 0..k-1:
        #       y[i] = z[i]
        #
        # This defines:
        #   y_new[i] = y_old[i] + alpha * y_old[k-1-i],  for all i in [0, k)
        #
        # We implement this in-place by updating disjoint pairs
        #   (i, j = k-1-i)
        # using only the OLD values (yi, yj). For each pair:
        #   y[i] = yi + alpha * yj
        #   y[j] = yj + alpha * yi
        #
        # For odd k, there is a middle index m = k//2 where i == j.
        # In that case:
        #   y_new[m] = y_old[m] + alpha * y_old[m]
        #            = (1 + alpha) * y_old[m]
        #
        # We first update all pairs (i, k-1-i) with i < k-1-i,
        # then, if k is odd, handle the middle element separately.
        for i in seq(0, k / 2):
            yi = y[i]
            yj = y[k - 1 - i]
            y[i] = yi + alpha * yj
            y[k - 1 - i] = yj + alpha * yi

        if k % 2 == 1:
            # Center element when k is odd: index m = k//2.
            # This matches y[m] = y[m] + alpha * y[m].
            yi = y[k / 2]
            y[k / 2] = (1.0 + alpha) * yi

        # Set y[k] to the new reflection coefficient.
        y[k] = alpha


# ---------------------------------------------------------------------------
# Scheduling: unroll the inner loops over i to improve ILP and SIMD usage.
# We deliberately:
#   - keep the outer k-loop sequential (true data dependence),
#   - preserve the per-k reduction order for 'sum' (only structural
#     loop transformations that do not change the iteration order).
# ---------------------------------------------------------------------------

# Start from the unscheduled kernel.
kernel_durbin_scheduled = kernel_durbin

# 1) Unroll the reduction loop over i inside the k-loop.
#    We:
#      - split the loop over i into tiles of size 4,
#      - fully unroll the inner tile loop.
#    This preserves the global iteration order of i while exposing
#    more ILP to the backend compiler.
sum_i_loop = kernel_durbin_scheduled.find_loop("i")
kernel_durbin_scheduled = divide_loop(
    kernel_durbin_scheduled, sum_i_loop, 4,
    ("i_sum_outer", "i_sum_inner"),
    tail="guard",
)
sum_i_inner = kernel_durbin_scheduled.find_loop("i_sum_inner")
kernel_durbin_scheduled = unroll_loop(kernel_durbin_scheduled, sum_i_inner)

# 2) Unroll the in-place update loop over i (the symmetric pair updates).
#    At this point, the only remaining 'for i in ...' loop is the
#    pair-update loop. We apply the same tile-size-4 / full-unroll
#    strategy as above.
update_i_loop = kernel_durbin_scheduled.find_loop("i")
kernel_durbin_scheduled = divide_loop(
    kernel_durbin_scheduled, update_i_loop, 4,
    ("i_upd_outer", "i_upd_inner"),
    tail="guard",
)
update_i_inner = kernel_durbin_scheduled.find_loop("i_upd_inner")
kernel_durbin_scheduled = unroll_loop(kernel_durbin_scheduled, update_i_inner)

# 3) Simplify the resulting code (clean up guards, constant expressions, etc.).
kernel_durbin_scheduled = simplify(kernel_durbin_scheduled)

# Expose the scheduled kernel under the original name expected by the driver.
kernel_durbin = kernel_durbin_scheduled
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to raw pointers. */
  kernel_durbin(/*ctxt=*/NULL,
                n,
                (DATA_TYPE*)POLYBENCH_ARRAY(r),
                (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
