from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Optimized Durbin kernel:
# - Preserves the original mathematical algorithm.
# - Eliminates the temporary vector z[n] by doing an in-place symmetric
#   update of y[0..k-1] at each step k, which halves the memory traffic
#   on y and reduces working-set size.

@proc
def kernel_durbin(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE
    tmp1: DATA_TYPE
    tmp2: DATA_TYPE

    # Initial conditions (k = 0 step)
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    # Main Durbin / Levinson–Durbin recursion:
    # k = 1, ..., n-1  (Exo's seq(1, n) iterates k in [1, n))
    for k in seq(1, n):
        # Update prediction error energy beta using previous alpha.
        beta = (1.0 - alpha * alpha) * beta

        # Compute sum = Σ_{i=0}^{k-1} r[k-1-i] * y[i]
        sum = 0.0
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        # New reflection coefficient alpha_k
        alpha = -(r[k] + sum) / beta

        # In-place symmetric update of y[0..k-1], eliminating z[0..k-1].
        #
        # Original code:
        #   for i in 0..k-1:
        #       z[i] = y[i] + alpha * y[k-1-i]
        #   for i in 0..k-1:
        #       y[i] = z[i]
        #
        # This defines, for all i in [0, k):
        #   y_new[i] = y_old[i] + alpha * y_old[k-1-i]
        #
        # The loop below computes exactly the same y_new in-place using
        # only old y values:
        #   - For even k, it visits each pair (i, k-1-i) exactly once.
        #   - For odd k, the middle element i == k-1-i is updated once
        #     and ends up with (1 + alpha) * y_old[i], matching the
        #     original two-loop formulation.
        #
        # Loop bound: i in [0, (k+1)/2)
        #   - This is ceil(k/2) iterations:
        #       * when k even: pairs cover all indices 0..k-1
        #       * when k odd: pairs plus the center index
        for i in seq(0, (k + 1) / 2):
            tmp1 = y[i]
            tmp2 = y[k - i - 1]
            y[i] = tmp1 + alpha * tmp2
            y[k - i - 1] = tmp2 + alpha * tmp1

